struct SebVersion {
    static constexpr uint32_t kId = 0x741u;
    static constexpr size_t kDlc = 8u;
    static constexpr bool kExtended = false;
    uint8_t seb_sw_version{};
    uint8_t seb_hw_version{};

    CodecStatus pack(uint8_t* dst, size_t len) const noexcept {
        if (!dst && kDlc != 0) return CodecStatus::NullBuffer;
        if (len < kDlc) return CodecStatus::BufferTooSmall;
        if (seb_sw_version > 254) return CodecStatus::ValueOutOfRange;
        if (seb_hw_version > 255) return CodecStatus::ValueOutOfRange;
        for (size_t i = 0; i < kDlc; ++i) dst[i] = 0;
        constexpr bool little = true;
        detail::insert(dst, 0u, 0u, 8u, little, static_cast<uint64_t>(seb_sw_version));
        detail::insert(dst, 1u, 0u, 8u, little, static_cast<uint64_t>(seb_hw_version));
        return CodecStatus::Ok;
    }

    static CodecStatus unpack(const uint8_t* src, size_t len, SebVersion& out) noexcept {
        if (!src && kDlc != 0) return CodecStatus::NullBuffer;
        if (len < kDlc) return CodecStatus::BufferTooSmall;
        SebVersion value{};
        constexpr bool little = true;
        value.seb_sw_version = static_cast<uint8_t>(detail::extract(src, 0u, 0u, 8u, little));
        if (value.seb_sw_version > 254) return CodecStatus::ValueOutOfRange;
        value.seb_hw_version = static_cast<uint8_t>(detail::extract(src, 1u, 0u, 8u, little));
        if (value.seb_hw_version > 255) return CodecStatus::ValueOutOfRange;
        out = value;
        return CodecStatus::Ok;
    }
    static constexpr double seb_sw_version_to_physical(uint8_t raw) noexcept {
        return static_cast<double>(raw) * 0.01 + 0.0;
    }
    static CodecStatus seb_sw_version_from_physical(double physical, uint8_t& raw) noexcept {
        const auto candidate = static_cast<int64_t>(std::llround((physical - 0.0) / 0.01));
        if (candidate < 0 || candidate > 254) return CodecStatus::ValueOutOfRange;
        raw = static_cast<uint8_t>(candidate);
        return CodecStatus::Ok;
    }
    static constexpr double seb_hw_version_to_physical(uint8_t raw) noexcept {
        return static_cast<double>(raw) * 0.1 + 0.0;
    }
    static CodecStatus seb_hw_version_from_physical(double physical, uint8_t& raw) noexcept {
        const auto candidate = static_cast<int64_t>(std::llround((physical - 0.0) / 0.1));
        if (candidate < 0 || candidate > 255) return CodecStatus::ValueOutOfRange;
        raw = static_cast<uint8_t>(candidate);
        return CodecStatus::Ok;
    }
};

